# ============================================================================= # IATB Paper Trading Launch Runbook — Windows 11 PowerShell # ============================================================================= # Production-grade sequential deployment script for PAPER trading mode # with Zerodha credentials from .env file. # # Usage: # .\scripts\PAPER_TRADING_LAUNCH_RUNBOOK.ps1 # # Prerequisites: # - Python 3.12+ installed # - Poetry installed (pip install poetry) # - Git installed # - .env file with Zerodha credentials (ZERODHA_API_KEY, ZERODHA_API_SECRET) # - config/settings.toml with execution_mode="paper" # ============================================================================= param( [int]$ObserveCycles = 3, [int]$ObserveInterval = 30, [switch]$SkipQualityGates, [switch]$SkipTests, [switch]$DryRun ) $ErrorActionPreference = "Stop" $StartTime = Get-Date # ============================================================================= # Helper Functions # ============================================================================= function Write-Header { param([string]$Title) $Border = "=" * 70 Write-Host "" Write-Host $Border -ForegroundColor Cyan Write-Host " $Title" -ForegroundColor Cyan Write-Host $Border -ForegroundColor Cyan } function Write-Step { param([string]$StepName, [int]$StepNum) $Border = "-" * 70 Write-Host "" Write-Host $Border -ForegroundColor Yellow Write-Host " Step ${StepNum}: $StepName" -ForegroundColor Yellow Write-Host $Border -ForegroundColor Yellow } function Write-Success { param([string]$Message) Write-Host " PASS: $Message" -ForegroundColor Green } function Write-Fail { param([string]$Message) Write-Host " FAIL: $Message" -ForegroundColor Red } function Write-Info { param([string]$Message) Write-Host " INFO: $Message" -ForegroundColor White } function Write-Warn { param([string]$Message) Write-Host " WARN: $Message" -ForegroundColor Yellow } # Track results $Results = @{} # ============================================================================= # Step 1: Verify Prerequisites # ============================================================================= Write-Step "Verify Prerequisites" 1 $PrereqOk = $true # Check Python try { $PythonVersion = python --version 2>&1 Write-Info "Python: $PythonVersion" if ($PythonVersion -notmatch "3\.1[2-9]") { Write-Warn "Python 3.12+ recommended. Found: $PythonVersion" } else { Write-Success "Python 3.12+ found" } } catch { Write-Fail "Python not found" $PrereqOk = $false } # Check Poetry try { $PoetryVersion = poetry --version 2>&1 Write-Info "Poetry: $PoetryVersion" Write-Success "Poetry found" } catch { Write-Fail "Poetry not found — install: pip install poetry" $PrereqOk = $false } # Check Git try { $GitVersion = git --version 2>&1 Write-Info "Git: $GitVersion" Write-Success "Git found" } catch { Write-Fail "Git not found" $PrereqOk = $false } # Check .env file if (Test-Path ".env") { Write-Success ".env file exists" # Check for Zerodha credentials $EnvContent = Get-Content ".env" -Raw $HasKey = $EnvContent -match "ZERODHA_API_KEY\s*=\s*\S+" $HasSecret = $EnvContent -match "ZERODHA_API_SECRET\s*=\s*\S+" if ($HasKey) { Write-Success "ZERODHA_API_KEY found in .env" } else { Write-Fail "ZERODHA_API_KEY not found in .env" $PrereqOk = $false } if ($HasSecret) { Write-Success "ZERODHA_API_SECRET found in .env" } else { Write-Fail "ZERODHA_API_SECRET not found in .env" $PrereqOk = $false } } else { Write-Fail ".env file not found — copy .env.example and fill credentials" $PrereqOk = $false } $Results["prerequisites"] = $PrereqOk if (-not $PrereqOk) { Write-Fail "Prerequisites check failed. Fix issues and re-run." exit 1 } # ============================================================================= # Step 2: Install Dependencies # ============================================================================= Write-Step "Install Dependencies" 2 if ($DryRun) { Write-Info "DRY RUN: Skipping poetry install" } else { try { Write-Info "Running: poetry install" poetry install 2>&1 | ForEach-Object { Write-Host " $_" } Write-Success "Dependencies installed" $Results["dependencies"] = $true } catch { Write-Fail "poetry install failed: $_" $Results["dependencies"] = $false exit 1 } } # ============================================================================= # Step 3: Validate Paper Setup # ============================================================================= Write-Step "Validate Paper Trading Setup" 3 if ($DryRun) { Write-Info "DRY RUN: Skipping setup validation" $Results["setup_validation"] = $true } else { try { Write-Info "Running: poetry run python scripts/validate_paper_setup.py" poetry run python scripts/validate_paper_setup.py 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -eq 0) { Write-Success "Setup validation passed" $Results["setup_validation"] = $true } else { Write-Fail "Setup validation failed" $Results["setup_validation"] = $false Write-Warn "Some checks failed. Review output above. Continuing..." } } catch { Write-Fail "Setup validation error: $_" $Results["setup_validation"] = $false } } # ============================================================================= # Step 4: Quality Gates (G1-G5) # ============================================================================= Write-Step "Quality Gates (Lint, Format, Security)" 4 if ($SkipQualityGates -or $DryRun) { Write-Info "Skipping quality gates (SkipQualityGates=$SkipQualityGates, DryRun=$DryRun)" $Results["quality_gates"] = $true } else { $GateOk = $true # G1: Ruff lint Write-Info "G1: Ruff lint check..." poetry run ruff check src/ tests/ 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -ne 0) { Write-Warn "G1: Ruff lint found issues" $GateOk = $false } else { Write-Success "G1: Ruff lint clean" } # G2: Ruff format check Write-Info "G2: Ruff format check..." poetry run ruff format --check src/ tests/ 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -ne 0) { Write-Warn "G2: Ruff format found issues" $GateOk = $false } else { Write-Success "G2: Ruff format clean" } # G4: Bandit security Write-Info "G4: Bandit security check..." poetry run bandit -r src/ -q 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -ne 0) { Write-Warn "G4: Bandit found issues" $GateOk = $false } else { Write-Success "G4: Bandit clean" } $Results["quality_gates"] = $GateOk } # ============================================================================= # Step 5: Run Tests (G6) # ============================================================================= Write-Step "Run Tests" 5 if ($SkipTests -or $DryRun) { Write-Info "Skipping tests (SkipTests=$SkipTests, DryRun=$DryRun)" $Results["tests"] = $true } else { try { Write-Info "Running: poetry run pytest tests/ -q --no-cov --tb=line" poetry run pytest tests/ -q --no-cov --tb=line 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -eq 0) { Write-Success "All tests passed" $Results["tests"] = $true } else { Write-Warn "Some tests failed (exit: $LASTEXITCODE)" $Results["tests"] = $false } } catch { Write-Fail "Test run error: $_" $Results["tests"] = $false } } # ============================================================================= # Step 6: Create Required Directories # ============================================================================= Write-Step "Create Required Directories" 6 $RequiredDirs = @("data", "logs", "cache", "data\audit", "data\backups") foreach ($Dir in $RequiredDirs) { if (-not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null Write-Info "Created: $Dir" } else { Write-Info "Exists: $Dir" } } Write-Success "All directories ready" $Results["directories"] = $true # ============================================================================= # Step 7: Launch Paper Trading # ============================================================================= Write-Step "Launch Paper Trading" 7 if ($DryRun) { Write-Info "DRY RUN: Would execute: poetry run python scripts/launch_paper_trading.py" $Results["paper_launch"] = $true } else { try { Write-Info "Running: poetry run python scripts/launch_paper_trading.py" poetry run python scripts/launch_paper_trading.py 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -eq 0) { Write-Success "Paper trading launch completed successfully" $Results["paper_launch"] = $true } else { Write-Fail "Paper trading launch failed (exit: $LASTEXITCODE)" $Results["paper_launch"] = $false } } catch { Write-Fail "Paper trading launch error: $_" $Results["paper_launch"] = $false } } # ============================================================================= # Step 8: Start Engine for Continuous Trading (Headless) # ============================================================================= Write-Step "Start Continuous Paper Trading Engine" 8 if ($DryRun) { Write-Info "DRY RUN: Would start engine: poetry run python -m iatb.core.runtime" Write-Info "To start manually: Start-Process -NoNewWindow -FilePath 'poetry' -ArgumentList 'run','python','-m','iatb.core.runtime'" $Results["engine_start"] = $true } else { try { Write-Info "Starting IATB runtime in background..." $EngineProcess = Start-Process -FilePath "poetry" -ArgumentList "run","python","-m","iatb.core.runtime" -PassThru -NoNewWindow Write-Info "Engine process ID: $($EngineProcess.Id)" Write-Info "Waiting 5 seconds for engine startup..." Start-Sleep -Seconds 5 if (-not $EngineProcess.HasExited) { Write-Success "Engine running (PID: $($EngineProcess.Id))" $Results["engine_start"] = $true } else { Write-Fail "Engine exited with code: $($EngineProcess.ExitCode)" $Results["engine_start"] = $false } } catch { Write-Warn "Engine start skipped: $_" $Results["engine_start"] = $false } } # ============================================================================= # Step 9: Observe Paper Trading Performance # ============================================================================= Write-Step "Observe Paper Trading Performance" 9 if ($DryRun) { Write-Info "DRY RUN: Would observe: poetry run python scripts/observe_paper_trading.py -n $ObserveCycles -i $ObserveInterval" $Results["observe"] = $true } else { try { Write-Info "Running observer for $ObserveCycles cycles ($ObserveInterval s interval)..." poetry run python scripts/observe_paper_trading.py -n $ObserveCycles -i $ObserveInterval 2>&1 | ForEach-Object { Write-Host " $_" } Write-Success "Observation complete" $Results["observe"] = $true } catch { Write-Warn "Observer error: $_" $Results["observe"] = $false } } # ============================================================================= # Step 10: Verify No Naive Datetime, No Float, No Print (G7-G9) # ============================================================================= Write-Step "Additional Validation Checks (G7-G9)" 10 if ($DryRun) { Write-Info "DRY RUN: Skipping G7-G9 checks" $Results["g7_g9"] = $true } else { $G7G9Ok = $true # G7: No float in financial paths Write-Info "G7: Checking for float in financial paths..." poetry run python scripts/check_g7_no_float.py 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -ne 0) { Write-Warn "G7: Float usage detected" $G7G9Ok = $false } # G8: No naive datetime Write-Info "G8: Checking for naive datetime..." poetry run python scripts/check_g8_no_naive_datetime.py 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -ne 0) { Write-Warn "G8: Naive datetime detected" $G7G9Ok = $false } # G9: No print statements Write-Info "G9: Checking for print() statements..." poetry run python scripts/check_g9_no_print.py 2>&1 | ForEach-Object { Write-Host " $_" } if ($LASTEXITCODE -ne 0) { Write-Warn "G9: print() statements detected" $G7G9Ok = $false } $Results["g7_g9"] = $G7G9Ok } # ============================================================================= # Step 11: Git Sync # ============================================================================= Write-Step "Git Sync" 11 if ($DryRun) { Write-Info "DRY RUN: Would sync git: add, commit, push" $Results["git_sync"] = $true } else { try { $Branch = git rev-parse --abbrev-ref HEAD 2>&1 Write-Info "Current branch: $Branch" $Status = git status --porcelain 2>&1 if ($Status) { Write-Info "Staging changes..." git add -A 2>&1 | ForEach-Object { Write-Host " $_" } $CommitMsg = "feat(scripts): add production paper trading launch scripts - $(Get-Date -Format 'yyyy-MM-dd')" Write-Info "Committing: $CommitMsg" git commit -m $CommitMsg 2>&1 | ForEach-Object { Write-Host " $_" } Write-Info "Pulling with rebase..." git pull --rebase --autostash origin $Branch 2>&1 | ForEach-Object { Write-Host " $_" } Write-Info "Pushing to origin/$Branch..." git push origin $Branch 2>&1 | ForEach-Object { Write-Host " $_" } Write-Success "Git sync completed" } else { Write-Info "No changes to commit" } $Results["git_sync"] = $true } catch { Write-Warn "Git sync issue: $_" $Results["git_sync"] = $false } } # ============================================================================= # Final Summary # ============================================================================= $Elapsed = (Get-Date) - $StartTime Write-Header "PAPER TRADING LAUNCH RUNBOOK — SUMMARY" Write-Host "" foreach ($Key in $Results.Keys) { $Value = $Results[$Key] $Status = if ($Value) { "PASS" } else { "FAIL" } $Color = if ($Value) { "Green" } else { "Red" } Write-Host (" {0,-25} {1}" -f $Key, $Status) -ForegroundColor $Color } Write-Host "" Write-Info "Elapsed: $($Elapsed.ToString('hh\:mm\:ss'))" $AllPassed = $Results.Values -notcontains $false if ($AllPassed) { Write-Host "" Write-Host "=" * 70 -ForegroundColor Green Write-Host " ALL STEPS PASSED — Paper Trading is Live!" -ForegroundColor Green Write-Host "=" * 70 -ForegroundColor Green Write-Host "" Write-Info "Next steps:" Write-Info " 1. Monitor: poetry run python scripts/observe_paper_trading.py" Write-Info " 2. Launch engine: poetry run python -m iatb.core.runtime" Write-Info " 3. Dashboard: poetry run python scripts/dashboard_sse.py" Write-Info " 4. Stop engine: Ctrl+C or kill process" } else { $Failed = $Results.Keys | Where-Object { -not $Results[$_] } Write-Host "" Write-Host "=" * 70 -ForegroundColor Red Write-Host " SOME STEPS FAILED: $($Failed -join ', ')" -ForegroundColor Red Write-Host "=" * 70 -ForegroundColor Red } # ============================================================================= # Validation + Git Status Report # ============================================================================= Write-Header "GIT SYNC REPORT" try { $Branch = git rev-parse --abbrev-ref HEAD 2>&1 $Commit = git rev-parse --short HEAD 2>&1 $Remote = git remote -v 2>&1 | Select-Object -First 2 $Unpushed = git log --oneline origin/$Branch..HEAD 2>&1 Write-Host " Branch : $Branch" Write-Host " Commit : $Commit" Write-Host " Remote : $($Remote -join ', ')" if ($Unpushed) { Write-Host " Unpushed: $Unpushed" -ForegroundColor Yellow } else { Write-Host " Unpushed: None (all synced)" -ForegroundColor Green } } catch { Write-Warn "Git report error: $_" } Write-Host "" Write-Info "Runbook completed at $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"